use vstd::prelude::*;

verus! {
    /// Given two non‐empty vectors x and y of f32,
    /// produces two matrices X and Y of shape (y.len() × x.len())
    /// such that
    ///   X[i][j] == x[j]
    ///   Y[i][j] == y[i]
    fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (res: (Vec<Vec<f32>>, Vec<Vec<f32>>))
        requires
            x.len() > 0,
            y.len() > 0,
        ensures
            // unpack the result
            let (X, Y) = res;
            // correct outer dimensions
            X.len() == y.len(),
            Y.len() == y.len(),
            // for every valid (i,j), the meshgrid property holds
            forall |i: usize, j: usize|
                i < y.len() && j < x.len() ==>
                    X[i].len() == x.len() &&
                    Y[i].len() == x.len() &&
                    X[i][j] == x[j] &&
                    Y[i][j] == y[i]
    {
        let m = y.len();
        let n = x.len();
        let mut X: Vec<Vec<f32>> = Vec::new();
        let mut Y: Vec<Vec<f32>> = Vec::new();
        let mut i: usize = 0;
        // build row by row
        while i < m
            invariant i <= m,
            invariant X.len() == i,
            invariant Y.len() == i,
            // all rows [0..i) satisfy the meshgrid property
            invariant forall |ii: usize, jj: usize|
                ii < i && jj < n ==>
                    X[ii].len() == n &&
                    Y[ii].len() == n &&
                    X[ii][jj] == x[jj] &&
                    Y[ii][jj] == y[ii],
            decreases m - i
        {
            // construct the i‐th row of X and Y
            let mut rowX: Vec<f32> = Vec::new();
            let mut rowY: Vec<f32> = Vec::new();
            let mut j: usize = 0;
            while j < n
                invariant j <= n,
                invariant rowX.len() == j,
                invariant rowY.len() == j,
                // rowX[0..j) == x[0..j) and rowY[0..j) == y[i]
                invariant forall |jj: usize|
                    jj < j ==>
                        rowX[jj] == x[jj] &&
                        rowY[jj] == y[i],
                decreases n - j
            {
                rowX.push(x[j]);
                rowY.push(y[i]);
                j += 1;
            }
            X.push(rowX);
            Y.push(rowY);
            i += 1;
        }
        (X, Y)
    }
}

